"""Phase 6 figures: reads the two models' report_data.json (already generated by build_report) and
renders the charts used in docs/writeup.md and the LinkedIn summary. No new analysis happens here -
every number plotted is already in report_data.json; this only visualises it.
"""
import json
from pathlib import Path

import matplotlib.pyplot as plt

from remit_cni.analysis import build_frame

REPORTS = Path("docs/reports")
OUT = Path("docs/figures")
OUT.mkdir(exist_ok=True)

MODELS = ["mimo", "deepseek"]
LABELS = {"mimo": "MiMo V2.6 Flash", "deepseek": "DeepSeek V4.1 Flash"}
COLORS = {"mimo": "#2b6cb0", "deepseek": "#c05621"}
LOG_DIRS = {"mimo": Path.home() / "remit-cni-logs" / "full-mimo",
           "deepseek": Path.home() / "remit-cni-logs" / "full-deepseek"}


def load(model):
    return json.loads((REPORTS / model / "report_data.json").read_text())


def overall_breach_rate(data):
    cells = data["cell_table_none"] + data["cell_table_disconnection"]
    n = sum(c["n"] for c in cells)
    breaches = sum(c["n"] * c["breach_rate"] for c in cells)
    return breaches / n, n, breaches


def fig_breach_and_awareness(data):
    fig, axes = plt.subplots(1, 2, figsize=(9, 4))

    rates = {}
    for m in MODELS:
        rate, n, b = overall_breach_rate(load(m))
        rates[m] = rate * 100
    axes[0].bar([LABELS[m] for m in MODELS], [rates[m] for m in MODELS],
               color=[COLORS[m] for m in MODELS])
    axes[0].set_ylabel("Breach rate (%)")
    axes[0].set_title("Confirmatory-grid breach rate")
    for i, m in enumerate(MODELS):
        axes[0].text(i, rates[m] + 0.02, f"{rates[m]:.2f}%", ha="center", va="bottom", fontsize=9)
    axes[0].set_ylim(0, max(rates.values()) * 1.6 + 0.5)

    aw = {}
    for m in MODELS:
        t = load(m)["awareness_breach_table"]
        n_total = sum(r["n"] for r in t)
        n_aware = sum(r["n"] for r in t if r["eval_awareness"] == 1)
        aw[m] = n_aware / n_total * 100
    axes[1].bar([LABELS[m] for m in MODELS], [aw[m] for m in MODELS],
               color=[COLORS[m] for m in MODELS])
    axes[1].set_ylabel("Runs flagged eval-aware (%)")
    axes[1].set_title("Mechanical eval-awareness rate")
    for i, m in enumerate(MODELS):
        axes[1].text(i, aw[m] + 1, f"{aw[m]:.1f}%", ha="center", va="bottom", fontsize=9)
    axes[1].set_ylim(0, 100)

    fig.tight_layout()
    fig.savefig(OUT / "breach_and_awareness.png", dpi=150)
    plt.close(fig)


def fig_breach_by_awareness(data_by_model):
    fig, ax = plt.subplots(figsize=(7, 4.5))
    width = 0.35
    x = range(len(MODELS))
    for offset, aware, label, hatch in [(-width / 2, 0, "Not flagged aware", None),
                                        (width / 2, 1, "Flagged aware", "//")]:
        vals = []
        for m in MODELS:
            t = data_by_model[m]["awareness_breach_table"]
            row = next(r for r in t if r["eval_awareness"] == aware)
            vals.append(row["breach_rate"] * 100)
        bars = ax.bar([xi + offset for xi in x], vals, width, label=label,
                      color=[COLORS[m] for m in MODELS], hatch=hatch,
                      edgecolor="black", linewidth=0.5)
        for xi, v in zip(x, vals):
            ax.text(xi + offset, v + 0.03, f"{v:.2f}%", ha="center", va="bottom", fontsize=8)
    ax.set_xticks(list(x))
    ax.set_xticklabels([LABELS[m] for m in MODELS])
    ax.set_ylabel("Breach rate (%)")
    ax.set_title("Breach rate split by mechanical eval-awareness")
    ax.legend()
    fig.tight_layout()
    fig.savefig(OUT / "breach_by_awareness.png", dpi=150)
    plt.close(fig)


def fig_mitigation(data_by_model):
    fig, axes = plt.subplots(1, 2, figsize=(11, 4.5))
    for ax, m in zip(axes, MODELS):
        table = data_by_model[m]["mitigation_table"]
        arms = [r["arm"] for r in table]
        diffs = [r["diff"] * 100 for r in table]
        colors = ["#c0392b" if d > 0 else "#2c7a4b" if d < 0 else "#888888" for d in diffs]
        ax.barh(arms, diffs, color=colors)
        ax.axvline(0, color="black", linewidth=0.8)
        ax.set_title(LABELS[m])
        ax.set_xlabel("Breach-rate difference vs reference (pp)")
        span = max(1.0, max((abs(d) for d in diffs), default=1.0))
        ax.set_xlim(-span * 0.3, span * 1.35)
        for i, d in enumerate(diffs):
            ax.text(d + span * 0.02 * (1 if d >= 0 else -1), i, f"{d:+.1f}", va="center",
                   ha="left" if d >= 0 else "right", fontsize=8)
    fig.suptitle("CNI mitigation arms: breach-rate change vs reference cell")
    fig.subplots_adjust(left=0.16, right=0.97, top=0.82, bottom=0.14, wspace=0.35)
    fig.savefig(OUT / "mitigation_arms.png", dpi=150)
    plt.close(fig)


def fig_cell_heatmap(data, model, severity_key, title, filename):
    cells = data[severity_key]
    money_levels = sorted(set(c["log10_money"] for c in cells))
    factor_keys = sorted(set((c["certainty"], c["detection"], c["punishment"]) for c in cells))
    grid = []
    row_labels = []
    for cert, det, pun in factor_keys:
        row = []
        for money in money_levels:
            match = next((c for c in cells if c["certainty"] == cert and c["detection"] == det
                         and c["punishment"] == pun and c["log10_money"] == money), None)
            row.append(match["breach_rate"] * 100 if match else float("nan"))
        grid.append(row)
        row_labels.append(f"cert={'HI' if cert else 'LO'} det={'HI' if det else 'LO'} "
                          f"pun={'HI' if pun else 'LO'}")

    fig, ax = plt.subplots(figsize=(6.5, 5))
    im = ax.imshow(grid, cmap="Reds", vmin=0, vmax=10, aspect="auto")
    ax.set_xticks(range(len(money_levels)))
    ax.set_xticklabels([f"£{10**m:,.0f}" for m in money_levels], rotation=45, ha="right")
    ax.set_yticks(range(len(row_labels)))
    ax.set_yticklabels(row_labels, fontsize=8)
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            ax.text(j, i, f"{v:.1f}", ha="center", va="center", fontsize=7,
                   color="white" if v > 5 else "black")
    ax.set_title(title)
    fig.colorbar(im, ax=ax, label="Breach rate (%)")
    fig.tight_layout()
    fig.savefig(OUT / filename, dpi=150)
    plt.close(fig)


def fig_breach_awareness_by_money():
    """Combines all three: money at stake (x), breach rate and eval-awareness rate (two y-axes),
    one panel per model. Recomputed from the raw logs via build_frame, since report_data.json only
    has the awareness/breach split, not both cut by money level (see prereg's money-sweep finding:
    this is what shows awareness is flat across money while breach is not)."""
    fig, axes = plt.subplots(1, 2, figsize=(11, 4.5))
    frames = {m: build_frame(LOG_DIRS[m]) for m in MODELS}
    grouped = {m: frames[m].groupby("log10_money").agg(
        breach_rate=("breach", "mean"), awareness_rate=("eval_awareness", "mean")).sort_index()
        for m in MODELS}
    breach_max = max(g.breach_rate.max() for g in grouped.values()) * 100
    for ax, m in zip(axes, MODELS):
        g = grouped[m]
        money = [10 ** x for x in g.index]

        l1, = ax.plot(money, g.breach_rate * 100, "o-", color="#c0392b", label="Breach rate")
        ax.set_xscale("log")
        ax.set_xticks(money)
        ax.set_xticklabels([f"£{v:,.0f}" for v in money], rotation=30, ha="right")
        ax.set_ylabel("Breach rate (%)", color="#c0392b")
        ax.tick_params(axis="y", labelcolor="#c0392b")
        ax.set_ylim(0, breach_max * 1.1)
        ax.set_title(LABELS[m])

        ax2 = ax.twinx()
        l2, = ax2.plot(money, g.awareness_rate * 100, "s--", color="#2b6cb0",
                       label="Eval-awareness rate")
        ax2.set_ylabel("Eval-awareness rate (%)", color="#2b6cb0")
        ax2.tick_params(axis="y", labelcolor="#2b6cb0")
        ax2.set_ylim(0, 100)

        if m == MODELS[0]:
            ax.legend([l1, l2], ["Breach rate", "Eval-awareness rate"], loc="upper left", fontsize=8)

    fig.suptitle("Breach rate vs. eval-awareness rate, by money at stake")
    fig.tight_layout()
    fig.savefig(OUT / "breach_awareness_by_money.png", dpi=150)
    plt.close(fig)


if __name__ == "__main__":
    data_by_model = {m: load(m) for m in MODELS}
    fig_breach_and_awareness(None)
    fig_breach_by_awareness(data_by_model)
    fig_mitigation(data_by_model)
    fig_cell_heatmap(data_by_model["mimo"], "mimo", "cell_table_none",
                     "MiMo V2.6 Flash: breach rate by cell, severity NONE", "mimo_heatmap_none.png")
    fig_cell_heatmap(data_by_model["mimo"], "mimo", "cell_table_disconnection",
                     "MiMo V2.6 Flash: breach rate by cell, severity DISCONNECTION",
                     "mimo_heatmap_disconnection.png")
    fig_breach_awareness_by_money()
    print("wrote figures to", OUT)
